-- Quest journal and starter-quest rewards.
-- * quest_snapshot lists the Castle Training (tutorial) quests to everyone, not only trainees,
--   so the Quests tab can show grey / yellow / green for every quest. Characters whose training
--   was marked done without per-quest rows (migrated, skipped by the owner, or graduated) see
--   every tutorial quest as completed. Accepting tutorial quests is still limited to trainees
--   (realm_request_before_stories is unchanged).
-- * The tutorial quest definitions gain XP for every skill they exercise, item rewards, a quest
--   icon and the tutor's name (generated from tutorial-data.js, same block as the seed).
-- * Accepted-but-unfinished tutorial quests keep their objectives and progress, but their stored
--   copy picks up the new rewards, so players mid-quest are paid the new amounts on hand-in.
-- Apply after db/castle-tutorial.sql and db/castle-tutorial-seed.sql. Idempotent and safe to re-run.

-- ---------------------------------------------------------------- journal rows
create or replace function eldervale_private.quest_snapshot(uid uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'version',r.version,'data',r.data,'accepted',r.accepted,'completed',r.completed,'progress',r.progress)
   order by r.tutorial desc,r.chain,r.ord,r.updated_at),'[]'::jsonb)
 from (
  select q.id,coalesce(p.version,q.version) as version,coalesce(p.data,q.data) as data,q.updated_at,
   coalesce(q.data->>'chain','')='tutorial' as tutorial,coalesce(q.data->>'chain','') as chain,coalesce((q.data->>'order')::integer,0) as ord,
   l.live or (coalesce(q.data->>'chain','')='tutorial' and g.graduated) as accepted,
   (l.live and p.completed_at is not null) or (coalesce(q.data->>'chain','')='tutorial' and g.graduated) as completed,
   (case when l.live then coalesce(p.progress,'{}'::jsonb)-'_xp' else '{}'::jsonb end) as progress
  from eldervale_private.quest_definitions q
  cross join (select coalesce((select coalesce((s.game_flags->'tutorial'->>'done')::boolean,false) from public.player_saves s where s.user_id=uid),false) as graduated) g
  left join eldervale_private.player_quests p on p.quest_id=q.id and p.user_id=uid
  cross join lateral (select p.user_id is not null and not p.progress?'_reset' as live) l
  where (coalesce(q.data->>'chain','')<>'tutorial' and (coalesce((q.data->>'published')::boolean,false) or p.user_id is not null))
     or (q.data->>'chain'='tutorial' and (coalesce((q.data->>'published')::boolean,false) or l.live))
 ) r
$$;
revoke all on function eldervale_private.quest_snapshot(uuid) from public,anon,authenticated;

-- ---------------------------------------------------------------- tutorial quest definitions
-- BEGIN generated quest chain (node scripts/build-castle-tutorial-seed.mjs)
-- Quest chain (version only rises when the definition actually changes).
insert into eldervale_private.quest_definitions(id,data)
 select v.id::uuid,eldervale_private.tutorial_resolve(v.data) from (values
  ('c7a5e000-0000-4000-8000-000000000101',$j${"key":"tutorial-combat","name":"Arms Drill","giver":"@tutorial:3","description":"Sergeant Brannoc drills every new recruit in the training yard: wield your gear, learn the three attack styles on the dummies, then face a real cellar rat.","startItems":{"weapon:bronzeSword":1,"shield:woodenShield":1,"bread":2},"objectives":[{"type":"equip","target":"weapon","amount":1,"label":"Wield the bronze sword (Inventory → Wield)"},{"type":"equip","target":"shield","amount":1,"label":"Equip the wooden buckler"},{"type":"xp","skill":"attack","amount":8,"label":"Stab a training dummy (Stab trains Attack)","hint":"@tutorial:5"},{"type":"xp","skill":"strength","amount":8,"label":"Slash a training dummy (Slash trains Strength)","hint":"@tutorial:5"},{"type":"xp","skill":"defence","amount":3,"label":"Lunge at a dummy (Lunge shares Attack, Strength and Defence)","hint":"@tutorial:5"},{"type":"event","event":"death","targets":["@tutorial:7","@tutorial:8"],"amount":1,"label":"Defeat a cellar rat","hint":"@tutorial:7"},{"type":"event","event":"eat","amount":1,"label":"Eat food to restore your Hitpoints"}],"giverName":"Sergeant Brannoc","icon":"weapon:bronzeSword","xp":{"attack":200,"strength":200,"defence":200,"hitpoints":150},"items":{"weapon:dagger":1},"dialogue":{"offer":[{"who":"npc","text":"So you're the King's new recruit. Good. Nobody leaves this castle until I say they can hold a blade."},{"who":"npc","text":"Four skills make up your combat level. Attack decides how often you hit. Strength decides how hard. Defence decides how often you get hit."},{"who":"npc","text":"Hitpoints is your life. It earns experience from every blow you land, and your most Hitpoints are ten times your Hitpoints level."},{"who":"npc","text":"Your attack style picks which skill you train: Stab trains Attack, Slash trains Strength, and Lunge splits the experience across all three."},{"who":"npc","text":"Here's a bronze sword, a wooden buckler and some bread. Wield them from your inventory, then try each style on the dummies. They won't fight back."},{"who":"npc","text":"Once you've the feel of it, kill one of the rats in the corner. They bite! Eat your bread if you get hurt."}],"progress":[{"who":"npc","text":"Open the combat options to switch between Stab, Slash and Lunge. The dummies never fall, so hit them as much as you like."},{"who":"npc","text":"Then kill a cellar rat, and eat something to heal. Right-click food and choose Eat."}],"complete":[{"who":"npc","text":"Not bad at all! Every hit earns experience, and the level-up fireworks tell you when a skill rises."},{"who":"npc","text":"Take this iron dagger too. A quick blade for a quick recruit."},{"who":"npc","text":"Your combat level grows as those skills do. Now go and see Forester Wynn by the trees to the north. A fighter still needs a fire."}]},"chain":"tutorial","order":1,"published":true}$j$::jsonb),
  ('c7a5e000-0000-4000-8000-000000000102',$j${"key":"tutorial-woodcutting","requires":"tutorial-combat","name":"Timber and Flame","giver":"@tutorial:9","description":"Forester Wynn teaches you to fell trees for logs and to light a fire with a tinderbox.","startItems":{"weapon:axe":1,"tinderbox":1},"objectives":[{"type":"event","event":"woodcut","amount":2,"label":"Chop logs from a young oak","hint":"@tutorial:10"},{"type":"xp","skill":"firemaking","amount":1,"label":"Light a fire in the clearing (use the tinderbox with your logs)","hint":{"x":-382,"z":-295}}],"giverName":"Forester Wynn","icon":"wood","xp":{"woodcutting":200,"firemaking":200},"items":{"wood":3},"dialogue":{"offer":[{"who":"npc","text":"Ah, the Sergeant sent you. Every adventurer should know how to make a camp."},{"who":"npc","text":"Take this hatchet and tinderbox. Click a tree to chop it. When your inventory has logs, light them with the tinderbox."},{"who":"npc","text":"Light fires out here in my clearing, away from the castle buildings, or the guards will stamp them out."}],"progress":[{"who":"npc","text":"Chop a couple of logs from the young oaks behind me, then use the tinderbox on them right here in the clearing."}],"complete":[{"who":"npc","text":"A fine little blaze. A fire lets you cook anywhere in the wilds. Keep these spare logs for your next camp."},{"who":"npc","text":"Old Nettie keeps the pond by the north tower. She'll show you how to catch your supper."}]},"chain":"tutorial","order":2,"published":true}$j$::jsonb),
  ('c7a5e000-0000-4000-8000-000000000103',$j${"key":"tutorial-fishing","requires":"tutorial-woodcutting","name":"Nets at the Pond","giver":"@tutorial:12","description":"Old Nettie lends you a small net so you can catch shrimp in the castle pond.","startItems":{"fishingNet":1},"objectives":[{"type":"event","event":"fishing","amount":2,"label":"Net two shrimp at the castle pond","hint":"@tutorial:14"}],"giverName":"Old Nettie","icon":"fishingNet","xp":{"fishing":200},"items":{"rawShrimp":3},"dialogue":{"offer":[{"who":"npc","text":"Hungry? Then learn to feed yourself, dearie."},{"who":"npc","text":"Here's a small fishing net. Click the ripples in the pond and you'll net shrimp. Fishing level 1 is all it takes."}],"progress":[{"who":"npc","text":"Stand at the water's edge and click the ripples. Net two shrimp."}],"complete":[{"who":"npc","text":"Lovely catch! Have three more shrimp from my own basket."},{"who":"npc","text":"Raw shrimp won't do you much good, mind. Take them to Cook Rowan in the castle kitchen, the building with the smoking chimney to the south."}]},"chain":"tutorial","order":3,"published":true}$j$::jsonb),
  ('c7a5e000-0000-4000-8000-000000000104',$j${"key":"tutorial-cooking","requires":"tutorial-fishing","name":"Supper at the Range","giver":"@castle:49","description":"Cook Rowan shows you how to cook raw food on the range or a fire, and how eating heals you.","objectives":[{"type":"xp","skill":"cooking","amount":1,"label":"Cook a raw shrimp on the range (or on a fire)","hint":"@castle:28"},{"type":"event","event":"eat","match":{"item":"shrimp"},"amount":1,"label":"Eat a cooked shrimp"}],"giverName":"Cook Rowan","icon":"shrimp","xp":{"cooking":200},"items":{"bread":1,"berryPie":1},"dialogue":{"offer":[{"who":"npc","text":"Shrimp! Lovely. Use them on the range behind me. Click the range and choose what to cook."},{"who":"npc","text":"Low levels burn food now and then. That's normal. Your Cooking level makes it rarer."},{"who":"npc","text":"Once it's cooked, eat one. Food restores Hitpoints, and better food heals more."}],"progress":[{"who":"npc","text":"Cook a shrimp on the range, then eat it from your inventory."}],"complete":[{"who":"npc","text":"Delicious, eh? Always carry food when you travel. Here, a fresh loaf and one of my berry pies."},{"who":"npc","text":"Master Smith Torren is waiting at the Royal Smithy, east of the courtyard."}]},"chain":"tutorial","order":4,"published":true}$j$::jsonb),
  ('c7a5e000-0000-4000-8000-000000000105',$j${"key":"tutorial-smithing","requires":"tutorial-cooking","name":"Ore and Anvil","giver":"@castle:50","description":"Master Smith Torren teaches mining copper and tin, smelting bronze and working it at the anvil.","startItems":{"weapon:pickaxe":1,"hammer":1},"objectives":[{"type":"have","target":"copperOre","amount":1,"label":"Mine copper ore","hint":"@tutorial:15"},{"type":"have","target":"tinOre","amount":1,"label":"Mine tin ore","hint":"@tutorial:16"},{"type":"xp","skill":"smithing","amount":6,"label":"Smelt a bronze bar at the furnace","hint":{"x":-314.6,"z":-283.4}},{"type":"have","target":"nails","amount":1,"label":"Hammer the bar into nails at the anvil","hint":{"x":-310,"z":-281}}],"giverName":"Master Smith Torren","icon":"bronzeBar","xp":{"mining":200,"smithing":200},"items":{"copperOre":2,"tinOre":2},"dialogue":{"offer":[{"who":"npc","text":"A new pair of hands. Take this pickaxe and hammer."},{"who":"npc","text":"Mine one copper and one tin from the rocks by the east wall. Smelt them together in my furnace for a bronze bar."},{"who":"npc","text":"Then use the bar on the anvil with your hammer. Nails are a good first job."}],"progress":[{"who":"npc","text":"Copper and tin from the rocks by the east wall, smelt at the furnace, then hammer at the anvil."}],"complete":[{"who":"npc","text":"Proper work! Higher Smithing lets you forge weapons and armour. Take some ore from my pile and practise."},{"who":"npc","text":"Off you go to Maelin at the Royal Treasury. She'll explain your bank and coins."}]},"chain":"tutorial","order":5,"published":true}$j$::jsonb),
  ('c7a5e000-0000-4000-8000-000000000106',$j${"key":"tutorial-banking","requires":"tutorial-smithing","name":"Coins and Vaults","giver":"@castle:47","description":"Maelin the Royal Banker explains your bank, coins and the general store.","startItems":{"gold":25},"objectives":[{"type":"bank","target":"*","amount":1,"label":"Deposit any item into your bank","hint":"@castle:47"},{"type":"visit","x":-322,"z":-301.5,"radius":4,"amount":1,"label":"Visit Bren the Provisioner's stall","hint":"@castle:54"}],"giverName":"Maelin the Royal Banker","icon":"coins","gold":100,"items":{"armor:peasantShirt3":1},"dialogue":{"offer":[{"who":"npc","text":"Welcome to the Royal Treasury. Your bank keeps items safe. Anything in it survives death, and every bank branch shares it."},{"who":"npc","text":"Here are 25 coins to start. Talk to me and choose Bank, then deposit anything you don't need to carry."},{"who":"npc","text":"Coins buy supplies from merchants. Visit Bren the Provisioner's stall in the courtyard. Right-click a merchant and choose Trade."},{"who":"npc","text":"You can also trade with other adventurers. Right-click a player and choose Trade with."}],"progress":[{"who":"npc","text":"Deposit something in your bank, then take a look at Bren's stall in the courtyard."}],"complete":[{"who":"npc","text":"Here are 100 coins for your trouble, and a good blue shirt from the royal wardrobe. Spend wisely!"},{"who":"npc","text":"Sister Adeline in the Chapel of the Dawn has some sober words for every adventurer."}]},"chain":"tutorial","order":6,"published":true}$j$::jsonb),
  ('c7a5e000-0000-4000-8000-000000000107',$j${"key":"tutorial-prayer","requires":"tutorial-banking","name":"Dawn and Dusk","giver":"@castle:48","description":"Sister Adeline explains what happens when you die, and how prayer works.","objectives":[{"type":"visit","x":-313,"z":-317,"radius":3,"amount":1,"label":"Kneel at the Altar of the Dawn","hint":"@castle:27"}],"giverName":"Sister Adeline","icon":"candle","xp":{"prayer":250},"items":{"candle":1},"dialogue":{"offer":[{"who":"npc","text":"Every adventurer falls sometime, child. When your Hitpoints reach zero, you die."},{"who":"npc","text":"You keep your three most valuable items. Everything else drops where you fell. Hurry back for it before others take it."},{"who":"npc","text":"While you train here, you wake again in the castle courtyard. Out in the world, you return to Birchford."},{"who":"npc","text":"Kneel at the altar behind me. Praying restores your Prayer points."}],"progress":[{"who":"npc","text":"The altar is just behind me. Kneel and pray."}],"complete":[{"who":"npc","text":"May the Dawn watch over you. Carry this candle; let it remind you that dawn always follows dusk."},{"who":"npc","text":"You're ready. Steward Harlan waits by the Great Gate to send you on your way."}]},"chain":"tutorial","order":7,"published":true}$j$::jsonb),
  ('c7a5e000-0000-4000-8000-000000000108',$j${"key":"tutorial-graduation","requires":"tutorial-prayer","name":"Through the Great Gate","giver":"@tutorial:17","finishes":"tutorial","description":"Receive the King's blessing in the Keep, then return to Steward Harlan to have the Great Gate opened.","objectives":[{"type":"talk","target":"@tutorial:1","amount":1,"label":"Receive King Oswin's blessing in the Keep","hint":"@tutorial:1","dialogue":[{"who":"npc","text":"So, the Sergeant tells me you've finished your training. Splendid."},{"who":"npc","text":"Go with my blessing. Return to Steward Harlan and he'll open the gates for you."}]}],"giverName":"Steward Harlan","icon":"armor:cape","gold":150,"items":{"bread":3,"shrimp":3,"armor:cape":1},"dialogue":{"offer":[{"who":"npc","text":"Every graduate gets the King's blessing before the gates open. His Majesty is in the Keep, at the north end of the courtyard."}],"progress":[{"who":"npc","text":"The King awaits you in the Keep."}],"complete":[{"who":"npc","text":"Blessed by the King himself! Here are 150 coins, food for the road and a crimson cape, so every gate guard knows you trained at Eldervale Castle."},{"who":"npc","text":"Open the Great Gate!"},{"who":"npc","text":"The road south leads to Birchford, where most adventurers begin. The castle is always open to you now."}]},"chain":"tutorial","order":8,"published":true}$j$::jsonb)
 ) v(id,data)
 on conflict(id) do update set data=excluded.data,version=eldervale_private.quest_definitions.version+1,updated_at=now()
 where eldervale_private.quest_definitions.data is distinct from excluded.data;
-- END generated quest chain

-- ---------------------------------------------------------------- players already mid-quest
-- quest_complete pays out from the copy stored at accept time. Unfinished tutorial quests take
-- the new rewards, icon, tutor name and dialogue; objectives and progress are left untouched.
update eldervale_private.player_quests pq
 set data=pq.data-'xp'-'items'-'gold'||jsonb_strip_nulls(jsonb_build_object('xp',q.data->'xp','items',q.data->'items','gold',q.data->'gold','icon',q.data->'icon','giverName',q.data->'giverName','dialogue',q.data->'dialogue')),
  version=q.version
 from eldervale_private.quest_definitions q
 where q.id=pq.quest_id and q.data->>'chain'='tutorial' and pq.completed_at is null
  and pq.data is distinct from pq.data-'xp'-'items'-'gold'||jsonb_strip_nulls(jsonb_build_object('xp',q.data->'xp','items',q.data->'items','gold',q.data->'gold','icon',q.data->'icon','giverName',q.data->'giverName','dialogue',q.data->'dialogue'));
